import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Checkbox,
  CircularProgress,
  FormControlLabel,
  FormGroup,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

import { RECALCULATION_TRIGGER_OPTIONS } from '../../shared/carbonCalculationLabels';

interface RecalculationPolicy {
  policyStatement?: string;
  triggers?: string[];
  lastUpdatedAt?: string;
}

export const RecalculationPolicyPanel: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const [policyStatement, setPolicyStatement] = useState('');
  const [selectedTriggers, setSelectedTriggers] = useState<string[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getMSMEProfile();
      const policy = (res?.data?.manufacturingProfile?.recalculationPolicy || {}) as RecalculationPolicy;
      setPolicyStatement(policy.policyStatement || '');
      setSelectedTriggers(Array.isArray(policy.triggers) ? policy.triggers : []);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Unable to load recalculation policy');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const toggleTrigger = (id: string) => {
    setSelectedTriggers((prev) =>
      prev.includes(id) ? prev.filter((t) => t !== id) : [...prev, id]
    );
    setSaved(false);
  };

  const save = async () => {
    setSaving(true);
    setError(null);
    setSaved(false);
    try {
      await ApiService.updateRecalculationPolicy({
        policyStatement,
        triggers: selectedTriggers,
      });
      setSaved(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to save recalculation policy');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Recalculation policy (ISO 14064)
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Document when and why the GHG inventory will be recalculated. Required for ISO 14064
          governance and assurance readiness.
        </Typography>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}
        {saved && (
          <Alert severity="success" sx={{ mb: 2 }}>
            Recalculation policy saved. An audit log entry was recorded.
          </Alert>
        )}

        <Stack spacing={2}>
          <TextField
            label="Policy statement"
            multiline
            minRows={3}
            fullWidth
            value={policyStatement}
            onChange={(e) => {
              setPolicyStatement(e.target.value);
              setSaved(false);
            }}
            placeholder="Describe your recalculation approach, approval process, and documentation requirements."
          />

          <Box>
            <Typography variant="subtitle2" gutterBottom>
              Recalculation triggers
            </Typography>
            <FormGroup>
              {RECALCULATION_TRIGGER_OPTIONS.map((opt: { id: string; label: string }) => (
                <FormControlLabel
                  key={opt.id}
                  control={
                    <Checkbox
                      checked={selectedTriggers.includes(opt.id)}
                      onChange={() => toggleTrigger(opt.id)}
                    />
                  }
                  label={opt.label}
                />
              ))}
            </FormGroup>
          </Box>

          <Button variant="contained" onClick={() => void save()} disabled={saving}>
            {saving ? 'Saving…' : 'Save recalculation policy'}
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default RecalculationPolicyPanel;
